use async_shutdown::ShutdownManager;
use fec_rs::ReedSolomon;
use tokio::sync::mpsc;
use std::time::{Duration, Instant};

use crate::crypto::encrypt_cbc;
use crate::session::SessionKeysReceiver;
use crate::session::manager::SessionShutdownReason;
use crate::session::stream::RtpHeader;

use crate::session::stream::audio::{AudioFrame, AudioPacketBatch};
use crate::session::stream::audio::OpusStreamConfig;

const NR_DATA_SHARDS: usize = 4;
const NR_PARITY_SHARDS: usize = 2;
const NR_TOTAL_SHARDS: usize = NR_DATA_SHARDS + NR_PARITY_SHARDS;
const MAX_SHARD_SIZE: usize = 2048_usize.div_ceil(16) * 16;

#[derive(Debug)]
#[repr(C)]
struct AudioFecHeader {
	pub shard_index: u8,
	pub payload_type: u8,
	pub base_sequence_number: u16,
	pub base_timestamp: u32,
	pub ssrc: u32,
}

pub(crate) struct AudioEncoder {}

impl AudioEncoder {
	#[allow(clippy::too_many_arguments)]
	pub fn spawn(
		sample_rate: u32,
		stream_config: &OpusStreamConfig,
		frame_rx: crossbeam_channel::Receiver<AudioFrame>,
		frame_recycle_tx: crossbeam_channel::Sender<AudioFrame>,
		keys_rx: SessionKeysReceiver,
		encrypt: bool,
		packet_tx: mpsc::Sender<AudioPacketBatch>,
		stop: ShutdownManager<SessionShutdownReason>,
		start_gate: super::AudioStartGate,
	) -> Result<(), ()> {
		tracing::debug!("Starting audio encoder.");
		tracing::debug!(
			"Creating audio encoder with sample rate {}, {} channels ({} streams, {} coupled).",
			sample_rate,
			stream_config.channels,
			stream_config.streams,
			stream_config.coupled_streams,
		);

		let mut encoder = opus::MSEncoder::new(
			sample_rate,
			stream_config.streams,
			stream_config.coupled_streams,
			&stream_config.mapping[..stream_config.channels as usize],
			opus::Application::LowDelay,
		)
		.map_err(|e| tracing::warn!("Failed to create audio encoder: {e}"))?;

		// Moonlight expects a constant bitrate.
		encoder
			.set_vbr(false)
			.map_err(|e| tracing::warn!("Failed to disable variable bitrate: {e}"))?;
		encoder
			.set_bitrate(opus::Bitrate::Bits(stream_config.bitrate as i32))
			.map_err(|e| tracing::warn!("Failed to set audio bitrate: {e}"))?;

		// libopus defaults to complexity 10, its most expensive setting. That
		// is a fine default on the desktop this code came from; here the same
		// cores are simultaneously capturing and H.264-encoding video, and the
		// encoder fell far enough behind to discard roughly one 5 ms frame in
		// six - not a glitch under load but a steady ~16% of the audio,
		// dropped silently, which is heard as constant crackle. Complexity 5
		// is a large speedup for a difference that is inaudible at this
		// bitrate on a handheld's game audio.
		if let Err(e) = encoder.set_complexity(5) {
			tracing::warn!("Failed to set audio encoder complexity: {e}");
		}

		let fec_encoder = ReedSolomon::new(NR_DATA_SHARDS, NR_PARITY_SHARDS)
			.map_err(|e| tracing::warn!("Failed to create FEC encoder: {e}"))?;

		let inner = AudioEncoderInner {};
		std::thread::Builder::new()
			.name("audio-encode".to_string())
			.spawn(move || {
				inner.run(
					frame_rx,
					frame_recycle_tx,
					fec_encoder,
					encoder,
					keys_rx,
					encrypt,
					packet_tx,
					stop,
					start_gate,
				)
			})
			.map_err(|e| tracing::error!("Failed to start audio encode thread: {e}"))?;

		Ok(())
	}
}

struct AudioEncoderInner {}

impl AudioEncoderInner {
	#[allow(clippy::too_many_arguments)]
	fn run(
		self,
		frame_rx: crossbeam_channel::Receiver<AudioFrame>,
		frame_recycle_tx: crossbeam_channel::Sender<AudioFrame>,
		mut fec_encoder: ReedSolomon,
		mut encoder: opus::MSEncoder,
		keys_rx: SessionKeysReceiver,
		encrypt: bool,
		packet_tx: mpsc::Sender<AudioPacketBatch>,
		stop: ShutdownManager<SessionShutdownReason>,
		start_gate: super::AudioStartGate,
	) {
		// Trigger session shutdown when the audio encoder stops.
		let _session_stop_token = stop.trigger_shutdown_token(SessionShutdownReason::AudioEncoderStopped);
		let _delay_stop = stop.delay_shutdown_token();

		// Wait for the start signal before entering the encode loop.
		let rt = tokio::runtime::Builder::new_current_thread()
			.enable_all()
			.build()
			.expect("Failed to build tokio runtime for audio encoder");
		if rt.block_on(stop.wrap_cancel(start_gate.wait())).is_err() {
			tracing::debug!("Audio encoder stopped before start signal.");
			return;
		}

		let mut sequence_number = 0u16;
		let mut audio_timestamp = 0u32;

		// For unknown reasons, the RS parity matrix computed by our RS implementation.
		// doesn't match the one Nvidia uses for audio data. I'm not exactly sure why,
		// but we can simply replace it with the matrix generated by OpenFEC which
		// works correctly. This is possible because the data and FEC shard count is
		// constant and known in advance.
		// Source: https://github.com/moonlight-stream/moonlight-common-c/blob/5de4a5b85a28d8d639482a1a105c3a06eb67a2fd/src/RtpAudioQueue.c#L57.
		// TODO: Find a way to fix this, it is very ugly..
		fec_encoder
			.set_parity_matrix(&[0x77, 0x40, 0x38, 0x0e, 0xc7, 0xa7, 0x0d, 0x6c])
			.expect("Moonlight audio parity matrix must match Reed-Solomon shard layout");
		let mut fec_encoder = fec_rs::ShardByShard::new(&fec_encoder);

		let mut shards = vec![vec![0u8; MAX_SHARD_SIZE]; NR_TOTAL_SHARDS];

		// These values will be used for the parity shards, but they need to be copied from the first data shard.
		let mut base_sequence_number = 0u16;
		let mut base_timestamp = 0u32;

		// A buffer for an audio sample after it has been encoded.
		// TODO: Decide the correct size for this buffer.
		let mut encoded_audio = vec![0u8; 1400];

		// Pre-seed the recycling pipeline with empty frames.
		for _ in 0..3 {
			let _ = frame_recycle_tx.send(AudioFrame {
				buf: Vec::new(),
				capture_ts_ms: 0, source_pts_ns: 0, discontinuity: false, queued_at: Instant::now(),
			});
		}

		let period = Duration::from_millis(5);
		let mut next_output = Instant::now();
		let mut expired = 0u64;
		let mut encoded_count = 0u64;
		let mut encode_max_us = 0u128;
		let mut send_wait_max_us = 0u128;
		let mut queue_age_max_us = 0u128;
		let mut report_at = Instant::now();
		while !stop.is_shutdown_triggered() {
			// A single clock owns pacing here, after all producer-side queues.
			// Never replay a long pause as a burst of already encoded packets.
			std::thread::sleep(next_output.saturating_duration_since(Instant::now()));
			let Some(frame) = receive_fresh_frame(&frame_rx, &frame_recycle_tx, &stop, &mut expired) else { break; };
			let now = Instant::now();
			if now > next_output + period { next_output = now; }
			next_output += period;
			queue_age_max_us = queue_age_max_us.max(frame.queued_at.elapsed().as_micros());

			// The source timeline reaches the encoder for diagnostics. RTP stays on
            // consecutive 5 ms steps so Moonlight's four-packet FEC blocks remain valid.
            if frame.discontinuity {
                tracing::debug!("audio source discontinuity at monotonic {} ns", frame.source_pts_ns);
            }
            // GameStream audio RTP timestamps use milliseconds, with one 5 ms step per encoded packet.
			let timestamp = audio_timestamp;
			let encode_started = Instant::now();
			let encoded_size = match encoder.encode_float(&frame.buf, &mut encoded_audio) {
				Ok(encoded_size) => encoded_size,
				Err(e) => {
					tracing::warn!("Failed to encode audio: {e}");
					let _ = encoder
						.reset_state()
						.map_err(|e| tracing::warn!("Failed to reset Opus encoder state: {e}"));
					// Return the frame for recycling even on error.
					let _ = frame_recycle_tx.try_send(AudioFrame {
						buf: frame.buf,
						capture_ts_ms: 0, source_pts_ns: 0, discontinuity: false, queued_at: Instant::now(),
					});
					continue;
				},
			};
			encode_max_us = encode_max_us.max(encode_started.elapsed().as_micros());
			encoded_count += 1;

			// Read current keys from watch channel.
			let keys = &*keys_rx.borrow();

			// Encrypt the audio data if encryption is enabled.
			let payload = match encrypt {
				true => {
					let iv = keys.remote_input_key_id as u32 + sequence_number as u32;
					let mut iv = iv.to_be_bytes().to_vec();
					iv.extend([0u8; 12]);
					match encrypt_cbc(&encoded_audio[..encoded_size], &keys.remote_input_key, &iv) {
						Ok(payload) => payload,
						Err(e) => {
							tracing::warn!("Failed to encrypt audio: {e}");
							let _ = frame_recycle_tx.try_send(AudioFrame {
								buf: frame.buf,
							capture_ts_ms: 0, source_pts_ns: 0, discontinuity: false, queued_at: Instant::now(),
							});
							continue;
						},
					}
				},
				false => encoded_audio[..encoded_size].to_vec(),
			};

			let shard = &mut shards[sequence_number as usize % NR_DATA_SHARDS];

			{
				// Set the RTP header in the memory of the shard.
				let rtp_header = unsafe { &mut *(shard.as_mut_ptr() as *mut RtpHeader) };
				rtp_header.header = 0x80u8.to_be();
				rtp_header.packet_type = 97u8.to_be();
				rtp_header.sequence_number = sequence_number.to_be();
				rtp_header.timestamp = timestamp.to_be();
				rtp_header.ssrc = 0;

				// For FEC, copy the sequence number and timestamp of the first of the sequence of audio packets.
				if (sequence_number as usize).is_multiple_of(NR_DATA_SHARDS) {
					// Copy some values, but note that they are big-endian (as expected by Moonlight).
					base_sequence_number = rtp_header.sequence_number;
					base_timestamp = rtp_header.timestamp;
				}
			}

			sequence_number = sequence_number.wrapping_add(1);
			audio_timestamp = audio_timestamp.wrapping_add(5);

			// Copy the payload to the shard.
			unsafe {
				std::ptr::copy_nonoverlapping(
					payload.as_ptr(),
					shard.as_mut_ptr().add(std::mem::size_of::<RtpHeader>()),
					payload.len(),
				);
			}

			// Crop the shard to the length that we want to send it.
			let data_shard_size = std::mem::size_of::<RtpHeader>() + payload.len();
			let data_shard = shard[..data_shard_size].to_vec();

			let mut packets = Vec::with_capacity(3);
			packets.push(data_shard);

			{
				// Create a view of just the data itself for encoding.
				let mut shards: Vec<&mut [u8]> = shards.iter_mut().map(|s| &mut s[..data_shard_size]).collect();
				if let Err(e) = fec_encoder.encode(&mut shards) {
					tracing::warn!("Failed to encode data shard in FEC block: {e}");
					break;
				}
			}

			// If the last packet, compute and send parity shards.
			if (sequence_number as usize).is_multiple_of(NR_DATA_SHARDS) {
				if fec_encoder.reset().is_err() {
					tracing::warn!("Parity is not ready, but we were expecting it to be ready.");
					break;
				}

				for (shard_index, shard) in shards[NR_DATA_SHARDS..].iter_mut().enumerate() {
					{
						let rtp_header = unsafe { &mut *(shard.as_mut_ptr() as *mut RtpHeader) };
						rtp_header.sequence_number = (sequence_number + shard_index as u16).to_be();
						rtp_header.packet_type = 127u8.to_be();
						rtp_header.timestamp = 0u32.to_be();
						rtp_header.ssrc = 0u32.to_be();
					}

					// Make room for the AudioFecHeader by moving the payload back.
					unsafe {
						std::ptr::copy(
							shard.as_mut_ptr().add(std::mem::size_of::<RtpHeader>()),
							shard
								.as_mut_ptr()
								.add(std::mem::size_of::<RtpHeader>() + std::mem::size_of::<AudioFecHeader>()),
							payload.len(),
						);
					}

					{
						let fec_header = unsafe {
							&mut *(shard.as_mut_ptr().add(std::mem::size_of::<RtpHeader>()) as *mut AudioFecHeader)
						};
						fec_header.shard_index = (shard_index as u8).to_be();
						fec_header.payload_type = 97u8.to_be();
						fec_header.base_sequence_number = base_sequence_number;
						fec_header.base_timestamp = base_timestamp;
						fec_header.ssrc = 0u32;
					}

					let parity_shard_size =
						std::mem::size_of::<RtpHeader>() + std::mem::size_of::<AudioFecHeader>() + payload.len();
					let parity_shard = shard[..parity_shard_size].to_vec();

					packets.push(parity_shard);
				}
			}
			let send_started = Instant::now();
			let (sent, completion) = tokio::sync::oneshot::channel();
			let delivered = rt.block_on(stop.wrap_cancel(async {
				packet_tx.send(AudioPacketBatch { packets, sent }).await.map_err(|_| ())?;
				completion.await.map_err(|_| ())
			}));
			if !matches!(delivered, Ok(Ok(()))) { break; }
			send_wait_max_us = send_wait_max_us.max(send_started.elapsed().as_micros());
			if report_at.elapsed() >= Duration::from_secs(10) {
				tracing::info!(encoded_count, expired, encode_max_us, send_wait_max_us,
					queue_age_max_us, "audio pipeline timing (10s maxima)");
				encode_max_us = 0; send_wait_max_us = 0; queue_age_max_us = 0;
				report_at = Instant::now();
			}

			// Return the empty frame for recycling.
			let _ = frame_recycle_tx.try_send(AudioFrame {
				buf: frame.buf,
				capture_ts_ms: 0, source_pts_ns: 0, discontinuity: false, queued_at: Instant::now(),
			});
		}

		tracing::debug!("Audio encoder stopped.");
	}
}

/// Drop expired, unencoded PCM. Keep at most four 5 ms blocks and never
/// manufacture RTP gaps by dropping packets after sequence/FEC assignment.
fn receive_fresh_frame(
    frames: &crossbeam_channel::Receiver<AudioFrame>,
    recycle: &crossbeam_channel::Sender<AudioFrame>,
    stop: &ShutdownManager<SessionShutdownReason>,
    expired: &mut u64,
) -> Option<AudioFrame> {
    let mut skipped = false;
    while !stop.is_shutdown_triggered() {
        let mut frame = match frames.recv_timeout(Duration::from_millis(5)) {
            Ok(frame) => frame,
            Err(crossbeam_channel::RecvTimeoutError::Timeout) => continue,
            Err(crossbeam_channel::RecvTimeoutError::Disconnected) => return None,
        };
        if frames.len() > 3 || frame.queued_at.elapsed() > Duration::from_millis(20) {
            *expired += 1;
            skipped = true;
            let _ = recycle.try_send(frame);
            continue;
        }
        frame.discontinuity |= skipped;
        return Some(frame);
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    fn frame(pts: u64, age: Duration) -> AudioFrame {
        AudioFrame { buf: vec![0.1; 480], capture_ts_ms: pts / 1_000_000,
            source_pts_ns: pts, discontinuity: false, queued_at: Instant::now() - age }
    }

    #[test]
    fn stalled_encoder_discards_old_pcm_before_rtp_assignment() {
        let (tx, rx) = crossbeam_channel::bounded(16);
        let (recycle, _) = crossbeam_channel::bounded(16);
        let stop = ShutdownManager::new();
        tx.send(frame(1, Duration::from_secs(1))).unwrap();
        for pts in 2..=7 { tx.send(frame(pts, Duration::ZERO)).unwrap(); }
        let mut expired = 0;
        let fresh = receive_fresh_frame(&rx, &recycle, &stop, &mut expired).unwrap();
        assert_eq!(fresh.source_pts_ns, 4);
        assert_eq!(expired, 3);
        assert!(fresh.discontinuity);
        assert_eq!(rx.len(), 3);
    }

    #[test]
    fn expired_last_frame_is_not_replayed_when_source_has_closed() {
        let (tx, rx) = crossbeam_channel::bounded(1);
        let (recycle, _) = crossbeam_channel::bounded(1);
        tx.send(frame(1, Duration::from_secs(1))).unwrap();
        drop(tx);
        let mut expired = 0;
        assert!(receive_fresh_frame(&rx, &recycle, &ShutdownManager::new(), &mut expired).is_none());
        assert_eq!(expired, 1);
    }

    #[tokio::test]
    async fn stalled_sender_bounds_encoded_backlog_and_shutdown_does_not_wait_for_ack() {
        let (frames, frame_rx) = crossbeam_channel::bounded(16);
        let (recycle, _) = crossbeam_channel::bounded(16);
        let (packets, mut packet_rx) = mpsc::channel(1);
        let (_keys, keys_rx) = tokio::sync::watch::channel(crate::session::SessionKeyData {
            remote_input_key: vec![], remote_input_key_id: 0,
        });
        let gate = super::super::AudioStartGate::new();
        let stop = ShutdownManager::new();
        AudioEncoder::spawn(48000, &super::super::OPUS_STEREO, frame_rx, recycle,
            keys_rx, false, packets, stop.clone(), gate.clone()).unwrap();
        gate.open();
        // Supply fresh startup PCM until the encoder is ready. A slow thread
        // start may legitimately expire the first block before any packet exists.
        let held = tokio::time::timeout(Duration::from_secs(5), async {
            loop {
                let _ = frames.try_send(frame(1, Duration::ZERO));
                tokio::select! {
                    packet = packet_rx.recv() => break packet.unwrap(),
                    _ = tokio::time::sleep(Duration::from_millis(5)) => {},
                }
            }
        }).await.unwrap();
        for pts in 2..=10 { frames.send(frame(pts, Duration::ZERO)).unwrap(); }
        // Hold completion as a stalled network sender would. Nothing else may
        // be encoded into an independent packet backlog while it is held.
        assert!(tokio::time::timeout(Duration::from_millis(30), packet_rx.recv()).await.is_err());
        stop.trigger_shutdown(SessionShutdownReason::UserStopped).unwrap();
        tokio::time::timeout(Duration::from_secs(2), stop.wait_shutdown_complete()).await.unwrap();
        assert!(packet_rx.recv().await.is_none());
        drop(held);
    }
}
